60	@RestController
61	@CrossOrigin(exposedHeaders = "errors, content-type")
62	@RequestMapping("/api")
63	public class OwnerRestControllerV1 implements OwnersApi {
64	
65	    /**
66	     * Syntactic email check: a non-empty local part, an {@code @}, and a dotted domain, with no
67	     * whitespace or additional {@code @} characters. Deliberately permissive - it enforces basic
68	     * address shape rather than full RFC 5322 conformance.
69	     */
70	    private static final Pattern EMAIL_PATTERN =
71	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
72	
73	    private final ClinicService clinicService;
74	
75	    private final OwnerMapper ownerMapper;
76	
77	    private final PetMapper petMapper;
78	
79	    private final VisitMapper visitMapper;
80	
81	    public OwnerRestControllerV1(ClinicService clinicService,
82	                                 OwnerMapper ownerMapper,
83	                                 PetMapper petMapper,
84	                                 VisitMapper visitMapper) {
85	        this.clinicService = clinicService;
86	        this.ownerMapper = ownerMapper;
87	        this.petMapper = petMapper;
88	        this.visitMapper = visitMapper;
89	    }
90	
91	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
92	    @Override
93	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
94	        Collection<Owner> owners;
95	        if (lastName != null) {
96	            owners = this.clinicService.findOwnerByLastName(lastName);
97	        } else {
98	            owners = this.clinicService.findAllOwners();
99	        }
100	        if (owners.isEmpty()) {
101	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
102	        }
103	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
104	    }
105	
106	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
107	    @Override
108	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
109	        Owner owner = this.clinicService.findOwnerById(ownerId);
110	        if (owner == null) {
111	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
112	        }
113	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
114	    }
115	
116	    /**
117	     * Rejects an owner payload that is missing or blank in any required field. The response body's
118	     * {@code errors} array lists the name of each offending field.
119	     *
120	     * @param ownerFieldsDto the owner payload to validate
121	     * @throws RequiredFieldsMissingException if one or more required fields are missing or blank
122	     */
123	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
124	        List<String> missingFields = new ArrayList<>();
125	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
126	            missingFields.add("firstName");
127	        }
128	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
129	            missingFields.add("lastName");
130	        }
131	        if (!StringUtils.hasText(ownerFieldsDto.getAddress())) {
132	            missingFields.add("address");
133	        }
134	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
135	            missingFields.add("city");
136	        }
137	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
138	            missingFields.add("telephone");
139	        }
140	        if (!missingFields.isEmpty()) {
141	            throw new RequiredFieldsMissingException(missingFields);
142	        }
143	    }
144	
145	    /**
146	     * Normalizes a telephone number into E.164 form. Spaces, dashes and brackets are stripped. A
147	     * leading '+' and its country code are kept as given; otherwise country code '+61' is assumed
148	     * and a single leading '0' is dropped from the national digits. The result must be a '+'
149	     * followed by 8 to 15 digits.
150	     *
151	     * @param telephone the raw telephone value from the request
152	     * @return the E.164 telephone (e.g. {@code +61412345678})
153	     * @throws InvalidFieldsException if the value cannot form a valid E.164 number
154	     */
155	    private String normalizeTelephone(String telephone) {
156	        if (telephone == null) {
157	            throw new InvalidFieldsException(List.of("telephone"));
158	        }
159	        String trimmed = telephone.trim();
160	        boolean international = trimmed.startsWith("+");
161	        String cleaned = trimmed.replaceAll("[\\s\\-()]", "");
162	        String digits;
163	        if (international) {
164	            digits = cleaned.substring(1);
165	        } else {
166	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
167	            digits = "61" + national;
168	        }
169	        if (!digits.matches("[0-9]{8,15}")) {
170	            throw new InvalidFieldsException(List.of("telephone"));
171	        }
172	        return "+" + digits;
173	    }
174	
175	    /**
176	     * Best-effort normalization of an existing owner's stored telephone into E.164 form for
177	     * duplicate comparison, returning {@code null} when the value cannot form valid E.164.
178	     *
179	     * @param telephone an existing stored telephone value, may be {@code null}
180	     * @return the E.164 form, or {@code null} when it cannot be normalized
181	     */
182	    private String toE164OrNull(String telephone) {
183	        if (telephone == null) {
184	            return null;
185	        }
186	        try {
187	            return normalizeTelephone(telephone);
188	        }
189	        catch (InvalidFieldsException ex) {
190	            return null;
191	        }
192	    }
193	
194	    /**
195	     * Normalizes an optional email address. Email is not required, so a missing or blank value is
196	     * accepted and yields {@code null} (no email stored). When a non-blank value is supplied it must
197	     * be a syntactically valid address; the accepted value is returned lower-cased.
198	     *
199	     * @param email the raw email value from the request, may be {@code null}
200	     * @return the lower-cased email, or {@code null} when none was supplied
201	     * @throws InvalidFieldsException if a non-blank value is not a syntactically valid address
202	     */
203	    private String normalizeEmail(String email) {
204	        if (email == null || email.isBlank()) {
205	            return null;
206	        }
207	        String trimmed = email.trim();
208	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
209	            throw new InvalidFieldsException(List.of("email"));
210	        }
211	        return trimmed.toLowerCase(Locale.ROOT);
212	    }
213	
214	    /**
215	     * Rejects a telephone that, once normalized, is already used by any existing owner. Existing
216	     * owners' telephones are normalized the same way before comparison so differently-formatted
217	     * values representing the same number are treated as duplicates.
218	     *
219	     * @param telephone the normalized (E.164) telephone of the owner being created
220	     * @throws DuplicateOwnerTelephoneException if another owner already uses the telephone
221	     */
222	    private void requireUniqueTelephone(String telephone) {
223	        boolean taken = this.clinicService.findAllOwners().stream()
224	            .map(Owner::getTelephone)
225	            .map(this::toE164OrNull)
226	            .filter(existing -> existing != null)
227	            .anyMatch(telephone::equals);
228	        if (taken) {
229	            throw new DuplicateOwnerTelephoneException(telephone);
230	        }
231	    }
232	
233	    /**
234	     * Collapses surrounding and internal whitespace and lower-cases a value so that owner household
235	     * fields (last name, address) can be compared case-insensitively with collapsed whitespace. A
236	     * {@code null} value normalizes to the empty string.
237	     *
238	     * @param value the raw field value, may be {@code null}
239	     * @return the trimmed, whitespace-collapsed, lower-cased form
240	     */
241	    private String normalizeHousehold(String value) {
242	        if (value == null) {
243	            return "";
244	        }
245	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
246	    }
247	
248	    /**
249	     * Rejects an owner whose last name and address already match another owner (compared
250	     * case-insensitively with collapsed whitespace) - i.e. they would share a household - unless the
251	     * request opts in via {@code sharesHousehold}. Existing owners' fields are normalized the same
252	     * way before comparison.
253	     *
254	     * @param lastName the last name of the owner being created
255	     * @param address the address of the owner being created
256	     * @throws DuplicateOwnerHouseholdException if another owner shares the household
257	     */
258	    private void requireUniqueHousehold(String lastName, String address) {
259	        String normalizedLastName = normalizeHousehold(lastName);
260	        String normalizedAddress = normalizeHousehold(address);
261	        boolean shared = this.clinicService.findAllOwners().stream()
262	            .anyMatch(existing -> normalizeHousehold(existing.getLastName()).equals(normalizedLastName)
263	                && normalizeHousehold(existing.getAddress()).equals(normalizedAddress));
264	        if (shared) {
265	            throw new DuplicateOwnerHouseholdException(lastName, address);
266	        }
267	    }
268	
269	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
270	    @Override
271	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
272	        validateRequiredFields(ownerFieldsDto);
273	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
274	        requireUniqueTelephone(telephone);
275	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
276	            requireUniqueHousehold(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
277	        }
278	        String email = normalizeEmail(ownerFieldsDto.getEmail());
279	        HttpHeaders headers = new HttpHeaders();
280	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
281	        owner.setTelephone(telephone);
282	        owner.setEmail(email);
283	        if (owner.getRegistrationDate() == null) {
284	            owner.setRegistrationDate(LocalDate.now());
285	        }
286	        this.clinicService.saveOwner(owner);
287	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
288	        headers.setLocation(UriComponentsBuilder.newInstance()
289	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
290	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
291	    }
292	
293	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
294	    @Override
295	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
296	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
297	        if (currentOwner == null) {
298	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
299	        }
300	        currentOwner.setAddress(ownerFieldsDto.getAddress());
301	        currentOwner.setCity(ownerFieldsDto.getCity());
302	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
303	        currentOwner.setLastName(ownerFieldsDto.getLastName());
304	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
305	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
306	        this.clinicService.saveOwner(currentOwner);
307	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
308	    }
309	
310	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
311	    @Transactional
312	    @Override
313	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
314	        Owner owner = this.clinicService.findOwnerById(ownerId);
315	        if (owner == null) {
316	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
317	        }
318	        this.clinicService.deleteOwner(owner);
319	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
320	    }
321	
322	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
323	    @Override
324	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
325	        Owner owner = this.clinicService.findOwnerById(ownerId);
326	        if (owner == null) {
327	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
328	        }
329	        HttpHeaders headers = new HttpHeaders();
330	        Pet pet = petMapper.toPet(petFieldsDto);
331	        owner.setId(ownerId);
332	        pet.setOwner(owner);
333	        pet.getType().setName(null);
334	        this.clinicService.savePet(pet);
335	        PetDto petDto = petMapper.toPetDto(pet);
336	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
337	            .buildAndExpand(pet.getId()).toUri());
338	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
339	    }
340	
341	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
342	    @Override
343	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
344	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
345	        if (currentOwner != null) {
346	            Pet currentPet = this.clinicService.findPetById(petId);
347	            if (currentPet != null) {
348	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
349	                currentPet.setName(petFieldsDto.getName());
350	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
351	                this.clinicService.savePet(currentPet);
352	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
353	            }
354	        }
355	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
356	    }
357	
358	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
359	    @Override
360	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
361	        HttpHeaders headers = new HttpHeaders();
362	        Visit visit = visitMapper.toVisit(visitFieldsDto);
363	        Pet pet = new Pet();
364	        pet.setId(petId);
365	        visit.setPet(pet);
366	        this.clinicService.saveVisit(visit);
367	        VisitDto visitDto = visitMapper.toVisitDto(visit);
368	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
369	            .buildAndExpand(visit.getId()).toUri());
370	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
371	    }
372	
373	
374	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
375	    @Override
376	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
377	        Owner owner = this.clinicService.findOwnerById(ownerId);
378	        if (owner != null) {
379	            Pet pet = owner.getPet(petId);
380	            if (pet != null) {
381	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
382	            }
383	        }
384	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
385	    }
386	}
